class Solution {
    public long largestPool(int[] walls) {
        int n = walls.length;
        long best = 0, pool = 0;
        for (int i = 0; i < n; i++) {
            int left = 0, right = 0;
            for (int k = 0; k <= i; k++) left = Math.max(left, walls[k]);
            for (int k = i; k < n; k++) right = Math.max(right, walls[k]);
            int water = Math.min(left, right) - walls[i];
            pool = water > 0 ? pool + water : 0;
            best = Math.max(best, pool);
        }
        return best;
    }
}

